+import {IncomingMessage, ServerResponse} from 'http';
+
+/**
+ * Middleware to restrict Metro Dev Server access to localhost by default.
+ * This prevents unauthenticated remote attackers from hitting sensitive endpoints.
+ */
+export function securityMiddleware(req: IncomingMessage, res: ServerResponse, next: () => void) {
+  const remoteAddress = req.socket.remoteAddress;
+  const isLocal = 
+    remoteAddress === '127.0.0.1' || 
+    remoteAddress === '::ffff:127.0.0.1' || 
+    remoteAddress === '::1';
+
+  if (!isLocal) {
+    res.statusCode = 403;
+    res.end('Forbidden: Metro Dev Server is only accessible from localhost.');
+    return;
+  }
+  next();
+}

